import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"title":"Architecture"},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md"}'),r={name:"concepts/architecture.md"};function o(p,e,i,l,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<blockquote><p>🚧 Wingport is in active development. The API described here is the v0.1 design. Star the repo to follow along, or join the early access list.</p></blockquote><h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────┐</span></span>
<span class="line"><span>│   Flutter app + Wingport SDK │   no keys in the binary</span></span>
<span class="line"><span>└──────────────┬──────────────┘</span></span>
<span class="line"><span>               │  HTTPS + user JWT</span></span>
<span class="line"><span>┌──────────────▼──────────────────────────────┐</span></span>
<span class="line"><span>│        YOUR Supabase project                 │</span></span>
<span class="line"><span>│  ┌────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │        Wingport gateway (edge fn)      │  │</span></span>
<span class="line"><span>│  └───┬──────────────┬───────────────┬────┘  │</span></span>
<span class="line"><span>│  ┌───▼────┐   ┌─────▼─────┐   ┌─────▼────┐  │</span></span>
<span class="line"><span>│  │  Auth  │   │ Postgres  │   │ Secrets  │  │</span></span>
<span class="line"><span>│  │  (JWT) │   │usage/quota│   │ API keys │  │</span></span>
<span class="line"><span>│  └────────┘   └───────────┘   └──────────┘  │</span></span>
<span class="line"><span>└──────────────┬──────────────────────────────┘</span></span>
<span class="line"><span>               │  provider call, your keys</span></span>
<span class="line"><span>     ┌─────────┼─────────┐</span></span>
<span class="line"><span>┌────▼───┐ ┌───▼────┐ ┌──▼─────┐</span></span>
<span class="line"><span>│Anthropic│ │ OpenAI │ │ Google │</span></span>
<span class="line"><span>└────────┘ └────────┘ └────────┘</span></span></code></pre></div><h2 id="request-lifecycle" tabindex="-1">Request lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request lifecycle&quot;">​</a></h2><ol><li><strong>The app calls the SDK.</strong> <code>wing.stream(model: &#39;claude-sonnet&#39;, prompt: ...)</code>. The SDK attaches the user&#39;s current Supabase session JWT.</li><li><strong>The gateway verifies the user.</strong> JWT verification happens locally against your project&#39;s signing secret — no network round-trip. The gateway now knows <em>which end user</em> is calling, not just &quot;the app&quot;.</li><li><strong>Quota check.</strong> The gateway reads the user&#39;s row in <code>wingport_usage</code>. Over their daily request or token limit? The request is rejected with <code>429</code> before a single provider token is spent.</li><li><strong>Provider call.</strong> The gateway pulls the key from your Supabase secrets, maps the request to the provider&#39;s API shape, and forwards it. If the primary provider errors and <code>fallback</code> is enabled, the request re-routes automatically.</li><li><strong>Streaming passthrough.</strong> Response tokens stream back through the gateway to the device as SSE. The gateway never buffers the full response.</li><li><strong>Metering.</strong> On completion, token counts are written to <code>wingport_usage</code> — your data, your database, queryable with SQL.</li></ol><h2 id="what-runs-where" tabindex="-1">What runs where <a class="header-anchor" href="#what-runs-where" aria-label="Permalink to &quot;What runs where&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Language</th><th>Runs on</th><th>You maintain?</th></tr></thead><tbody><tr><td>Dart SDK</td><td>Dart</td><td>The user&#39;s device</td><td>No — <code>pub upgrade</code></td></tr><tr><td>Gateway function</td><td>TypeScript (Deno)</td><td>Your Supabase edge</td><td>No — <code>wingport deploy</code> updates it</td></tr><tr><td>Config</td><td>TypeScript</td><td>Checked into your repo</td><td>Yes — it&#39;s ~15 lines</td></tr><tr><td>Usage tables</td><td>SQL</td><td>Your Postgres</td><td>No — migrations are generated</td></tr></tbody></table><hr>`,8)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
